const event = $('Verify signature').first().json.event;
const d = event.data;
const fmt = (day) => new Date(day + 'T00:00:00Z')
  .toLocaleDateString('en-GB', { day: 'numeric', month: 'short', timeZone: 'UTC' });
const range = d.startDate === d.endDate ? fmt(d.startDate) : `${fmt(d.startDate)} – ${fmt(d.endDate)}`;
const hi = `Hi ${d.recipient.firstName},`;
const sign = '\n\n— LendLoop';

const copy = {
  'loan.requested': [
    `${d.counterpartFirstName} wants to borrow your ${d.toolName}`,
    `${hi}\n\n${d.counterpartFirstName} has asked to borrow your ${d.toolName} for ${range}.\n\nApprove or decline: ${d.url}`,
  ],
  'loan.approved': [
    `Approved: ${d.toolName} for ${range}`,
    `${hi}\n\n${d.counterpartFirstName} approved your request to borrow the ${d.toolName} for ${range}. Arrange pick-up with them directly.\n\nYour requests: ${d.url}`,
  ],
  'loan.declined': [
    `Declined: ${d.toolName} for ${range}`,
    `${hi}\n\n${d.counterpartFirstName} can't lend the ${d.toolName} for ${range} this time. Another neighbour may have one.\n\nYour requests: ${d.url}`,
  ],
  'loan.cancelled': [
    `${d.counterpartFirstName} cancelled their request for your ${d.toolName}`,
    `${hi}\n\n${d.counterpartFirstName} no longer needs your ${d.toolName} for ${range}. Nothing for you to do.\n\nIncoming requests: ${d.url}`,
  ],
  'loan.returned': [
    `Thanks for returning the ${d.toolName}`,
    `${hi}\n\n${d.counterpartFirstName} marked the ${d.toolName} as returned. Thanks for being a good neighbour.\n\nYour requests: ${d.url}`,
  ],
}[event.type];

if (!copy) throw new Error(`Unknown event type: ${event.type}`);

return [{ json: {
  eventId: event.id,
  loanId: d.loanId,
  kind: event.kind,
  type: event.type,
  from: setting('LENDLOOP_FROM_EMAIL', { optional: true }) || 'LendLoop <no-reply@lendloop.app>',
  to: d.recipient.email,
  subject: copy[0],
  text: copy[1] + sign,
} }];

