return [{ json: signedCall('/n8n/events', {
  idempotencyKey: c.eventId,
  loanId: c.loanId,
  kind: c.kind,
  outcome: 'sent',
  detail: c.type === 'loan.requested' ? undefined : c.type.replace('loan.', '').replace(/^./, (s) => s.toUpperCase()),
}) }];

